type SupplementalQuestionSeed = {
  id: string;
  learningPath: Question["learningPath"];
  skill: string;
  skillTh: string;
  topic: string;
  topicTh: string;
  difficulty?: Question["difficulty"];
  question: string;
  questionTh: string;
  correct: string;
  correctTh: string;
  wrong: [string, string, string];
  wrongTh: [string, string, string];
  explanation: string;
  explanationTh: string;
  practicalExample: string;
  practicalExampleTh: string;
  keyTakeaway: string;
  keyTakeawayTh: string;
  hint: string;
  hintTh: string;
  vocabWord?: string;
  vocabTh?: string;
};

function supplementalQuestion(seed: SupplementalQuestionSeed): Question {
  const englishChoices = [seed.correct, ...seed.wrong];
  const thaiChoices = [seed.correctTh, ...seed.wrongTh];
  const ids = ["a", "b", "c", "d"] as const;
  const offset = seed.id.length % ids.length;
  const choices = ids.map((id, index) => {
    const sourceIndex = (index - offset + ids.length) % ids.length;
    return {
      id,
      text: englishChoices[sourceIndex],
      textTh: thaiChoices[sourceIndex],
    };
  });
  const correctChoiceId = ids[offset];
  const incorrectFeedback = ids.reduce<Record<string, string>>((feedback, id) => {
    if (id !== correctChoiceId) feedback[id] = "This option misses the main decision behind the question.";
    return feedback;
  }, {});
  const incorrectFeedbackTh = ids.reduce<Record<string, string>>((feedback, id) => {
    if (id !== correctChoiceId) feedback[id] = "ตัวเลือกนี้ยังไม่จับ decision สำคัญของคำถาม";
    return feedback;
  }, {});

  return {
    id: seed.id,
    learningPath: seed.learningPath,
    skill: seed.skill,
    skillTh: seed.skillTh,
    topic: seed.topic,
    topicTh: seed.topicTh,
    difficulty: seed.difficulty ?? "Junior",
    question: seed.question,
    questionTh: seed.questionTh,
    choices,
    correctChoiceId,
    explanation: seed.explanation,
    explanationTh: seed.explanationTh,
    incorrectFeedback,
    incorrectFeedbackTh,
    practicalExample: seed.practicalExample,
    practicalExampleTh: seed.practicalExampleTh,
    keyTakeaway: seed.keyTakeaway,
    keyTakeawayTh: seed.keyTakeawayTh,
    hint: seed.hint,
    hintTh: seed.hintTh,
    vocabulary: [
      vocab(
        `${seed.id}-vocab`,
        seed.vocabWord ?? seed.topic,
        seed.vocabTh ?? seed.topicTh,
        "noun",
        `A practical concept used in ${seed.skill}.`,
        `Use ${seed.vocabWord ?? seed.topic} to explain the decision clearly.`,
        `ใช้ ${seed.vocabWord ?? seed.topic} เพื่ออธิบาย decision ให้ชัด`,
        seed.learningPath,
        seed.topic,
      ),
    ],
  };
}

